import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script path {script_path} does not exist")
    proc = subprocess.Popen(script_path, shell=True)
    pid = proc.pid
    cpu_total = 0.0
    mem_total = 0
    start_time = time.time()
    try:
        p = psutil.Process(pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    while True:
        if time.time() - start_time > timeout:
            proc.terminate()
            break
        try:
            if not p.is_running():
                break
            cpu_total += p.cpu_percent(interval=0.0)
            mem_total += p.memory_info().rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
        time.sleep(0.1)
    if proc.poll() is None:
        proc.terminate()
